    int32_t ai_player_relation[8]; // diplomatic relation toward each player index 0..7: +1 = self/friendly, -1 = hostile. Initialised by llm_strat_spawn_ai_base / _spawn_invasion_force / llm_strat_init_human_player_data as (i == self) ? 1 : -1. Every AI hostility test is a sign test (< 0 = hostile), e.g. llm_strat_ai_group_area_scan_hostile indexing it by the tile owner nibble. THIRD of three consecutive int[8] per-opponent blocks -- ai_intel_seen_count (+0x28488), ai_intel_flags (+0x284a8), this (+0x284c8) -- exactly 0x20 apart and zeroed in the same init loop. (The two siblings were undefined bytes until they were named 2026-08-02; this sentence used to say so.)
    int32_t ai_train_queued_by_unit_type[100]; // How many training entries the AI currently has queued for each UNIT TYPE: INC'd by llm_strat_ai_queue_train_unit (0x004e282e) and DEC'd by llm_strat_ai_queue_flush_unit_train_entries (0x004e2c3f), both indexing by the unit type the caller passed. Zeroed at spawn over 0..G_UNIT_COUNT_TOTAL inclusive. Extent int[100] is fixed by adjacency: +0x284e8 + 100*4 lands exactly on ai_train_queued_by_ai_unit below. Named 2026-08-02 (RI-AI); previously undefined bytes.
    int32_t ai_train_queued_by_ai_unit[12]; // The same queued-training count aggregated by AI ROLE instead of by type -- indexed by `cfg::final::struct::Unit[type].ai_unit` (+0x237 of the 0x23f-byte cfg Unit record), maintained in lockstep with ai_train_queued_by_unit_type by the same INC/DEC pair (0x004e2837 / 0x004e2c5f). llm_strat_ai_plan_unit_training reads it to pick the role with the FEWEST queued (running-minimum at 0x004e6e68). Extent int[12] is the remaining gap to ai_score_cat_1. Named 2026-08-02 (RI-AI); previously undefined bytes.
    int32_t ai_score_cat_1; // build-category score cache (llm_strat_ai_score_build_categories): built+queued count for ai_build category 1
    int32_t ai_score_cat_0x20; // built+queued count for ai_build category 0x20
