    int32_t ai_score_cat_0x22; // built+queued count for ai_build category 0x22
    int32_t ai_score_cat_0x10; // built+queued count for ai_build category 0x10
    int32_t ai_score_cat_0x11; // built+queued count for ai_build category 0x11
