// llm_map_region (size 0x420, Ghidra category /Manual/map)
struct mh_llm_map_region {
    uint16_t index; // region id (index into _G_LLM_MAP_REGION_BY_INDEX)
    uint8_t x; // flood-fill seed tile
    uint8_t y;
    uint32_t cell_count; // cells claimed by this region (merge picks the smaller region)
    uint32_t neighbor_count; // entries in both 128-slot arrays
    struct mh_llm_map_region * neighbors[128]; // adjacent regions (serialized as indices, re-resolved on load)
    uint32_t neighbor_data[128]; // shared-BORDER LENGTH per neighbor, in tiles -- PROVEN 2026-08-07, was 'border length / link cost? unproven'. llm_map_region_add_adjacency_edge is called once per right/down tile pair that crosses a region boundary and increments this by 1 on BOTH sides, so the value counts tile-edge crossings. Parallel to neighbors[]; only the first neighbor_count entries are live.
    struct mh_llm_map_region * next; // intrusive list link (active list or free list)
    int32_t route_bfs_dist; // Scratch BFS-from-source distance/visited marker for llm_map_region_find_route: reset to 0 for every region at each find_route call, source=1, each newly-enqueued neighbor = parent+1; 0 doubles as 'unvisited'. (llm)
    struct mh_llm_map_region * route_parent; // BFS predecessor / route-chain link: written by find_route during expansion (neighbor.route_parent=current), walked BACKWARD from goal to reconstruct the path and FORWARD as a 'next' by route_mark_shared_nodes over the reconstructed chain. (llm)
    int32_t route_mark; // Multi-pass scratch flag (same 4 bytes reused by two non-concurrent subsystems): (a) find_route post-process sets 1 for regions on the discovered path, route_mark_shared_nodes sets 2 for a shared neighbor of two adjacent path regions; (b) pathfind_mark_group_member_regions seeds 2 for member-occupied regions and flood_reachable gates its flood on (route_mark!=0). 0=off. [confidence: med -- the reset discipline BETWEEN the two passes is unverified] (llm)
    struct mh_llm_map_region * prev; // set to 0, never seen read
};

