// llm_strat_group_scratch_member (size 0x14, Ghidra category /llm)
struct mh_llm_strat_group_scratch_member {
    int32_t tile_col; // Member's tile column. Written by llm_strat_group_move_register_member from units[p][i].x at registration; on a plain multi-member move llm_strat_group_move_order_commit overwrites it with the planner's DESTINATION column (_G_LLM_STRAT_GROUP_MEMBER_TILE) once the wave is committed, so the field means 'current' before the commit and 'target' after it.
    int32_t tile_row; // Member's tile row; same lifecycle as tile_col (start row, then the planner's destination row). Read as a byte in places -- only the low byte is ever significant, tile coords are 0..255.
    int32_t wave_rank; // Movement-wave / cluster rank, -1 = unassigned. llm_strat_pathfind_route_leg_group_and_sort seeds every row to -1, then walks the members in ascending distance-to-goal order and, for each still-unassigned one, bumps a running rank and calls llm_strat_claim_free_slots_within_dist to stamp that rank onto EVERY unassigned member within a distance threshold of it. The array is then qsorted on this field, so llm_strat_unit_state_group_marshal can commit the group one rank at a time -- these are the 'heading-classed waves' of the 0xa->0xb->0xc chain.
    int32_t unit_idx; // Index into units[player][] for this member. This is the field the former _G_LLM_STRAT_GROUP_MEMBER_UNIT_SCRATCH symbol pointed at (it was the array's 4th column mistaken for a standalone dword at 0x00ae2e54); consumers index it as (&SCRATCH)[i*5].
    int32_t saved_passable; // The member tile's passable[] value as it was BEFORE registration. llm_strat_group_move_register_member saves it here and then writes units[p][i].origin_tile_was_passable over passable[x][y], i.e. it temporarily lifts every group member off the collision map so the group pathfinder does not treat its own members as obstacles; llm_strat_unit_state_group_marshal restores this value once the wave is committed. Losing this field would make a group deadlock on itself.
};

// llm_strat_heading_slot (size 0x10, Ghidra category /llm)
struct mh_llm_strat_heading_slot {
    int32_t cand_facing; // SLOT 0 of each heading's 3 is the only one read for this field. Small class id in {1,2,3} (init 1; the initializer raises some headings to 2 or 3). llm_strat_unit_group_step_ground reads TABLE[cur_unit->heading*3].cand_facing into a local (0x00483616) and (a) compares it for EQUALITY against TABLE[other_unit->heading*3].cand_facing to test whether two units' headings are compatible (0x004838c0), (b) switches on ==1/==2/==3 and REASSIGNS the local (0x00483c4c..0x00483caa). So it is a per-heading PATH-SHAPE CLASS, not a facing -- the name predates that reading and is not yet re-derived. NOT a per-slot field.
    int32_t turn_delta; // Per-slot. Passed VERBATIM as llm_strat_trace_greedy_path's 3rd argument, `mode` (push at 0x004836b7/0x00483d62/0x00484454). -1 is the INACTIVE-SLOT SENTINEL: llm_strat_unit_group_step_ground guards each of the 3 slots with `> -1` (0x00483685 CMP / 0x0048368c JG) and skips the slot otherwise -- the slot loop bound is a fixed 3 (0x00483668), so this field, not a count, is what ends the candidate list. Initializer values are -1 (default) and 0..6. Whether `turn delta` or `path mode` is the better reading is OPEN -- it depends on trace_greedy_path's own `mode` parameter, not re-derived here.
    int32_t start_col_delta; // Per-slot X (COLUMN) delta applied to the greedy-path START COLUMN. Re-derived 2026-08-20: the previous comment `unused/filler (init 0)` was WRONG -- llm_strat_unit_group_step_ground reads it at NINE sites (0x00483700, 0x004837cb, 0x00483a54, 0x00483db1, 0x00483e97, 0x00484126, 0x004844a3, 0x00484589, 0x00484818), each as `start_col = (local + start_col_delta) & general.width_mask` pushed as llm_strat_trace_greedy_path's 1st argument `start_col`. Symmetric with start_row_delta on the row axis; the WIDTH_MASK vs HEIGHT_MASK pairing is what fixes which axis is which. llm_strat_group_step_heading_table_init writes it 0/+1/-1 -- a tile step, not filler.
    int32_t start_row_delta; // Per-slot Y (ROW) delta applied to the greedy-path START ROW -- the twin of start_col_delta. Read at nine sites (0x004836d7, 0x004837fb, 0x00483a98, 0x00483d85, 0x00483eca, 0x0048416a, 0x00484477, 0x004845bc, 0x0048485c), each as `start_row = (local + start_row_delta) & general.height_mask` pushed as llm_strat_trace_greedy_path's 2nd argument `start_row`. Renamed from `override_val` 2026-08-20: that name recorded only that the initializer overrides it per heading, not what it means. Initializer values 0/+1/-1.
};

