    uint16_t right_frame_count; // Animation frame count of the RIGHT leaf, same computation as left_frame_count (fill 0x00439a4a-0x00439a67, finalize 0x00439b02-0x00439b4d, zeroed 0x00437bc8) -- AND the one the animation actually uses: llm_tact_door_tick loads it at 0x00432332 and compares it against frame_index at 0x00432339 to detect 'fully open' (state 1 -> 2).
