// llm_tact_unit_cmd_entry (size 0xb, Ghidra category /llm)
struct mh_llm_tact_unit_cmd_entry {
    uint8_t interrupt_flag; // Per-entry 'who issued this / may it be overridden' byte -- the entry's LEADING member, which is why the queue is based at tact_unit_record+0x54 and not +0x55. Written from llm_tact_unit_enqueue_command's 3rd param (register BL) at 0x0042b898, in the same six-store block that writes op and arg0..arg3 at the SAME slot index. Read back verbatim by llm_tact_unit_cmd_queue_resubmit_run (0x00430712). Both enqueue (0x0042b400) and llm_tact_unit_owner_tick (0x0043365e) refuse to act on the current slot when it is 0 while op != 0 and move_retry_wait == 0, so 0 marks a protected/uninterruptible command. The shipped debug overlay calls it `who`: llm_tact_render_view prints it beside op with the format at 0x00500338, "%2d. nr.com:%2d com:%2d who:%1d". Call-site polarity reads as issuer rather than a plain flag (player input -> 0, AI owner tick and mission load -> 1), which is why the name is the parameter's and the reading is left stated rather than settled. NOT cleared by llm_tact_unit_cmd_advance, which zeroes op and the four args only (0x004312b4-0x0043130c) -- so this byte is STALE whenever op == 0. Harmless today because every guard pairs it with op != 0, but a reimplementation that zero-fills the whole entry on dequeue would diverge on a byte-compare of the queue region.
    uint16_t op; // Command opcode; 0 = slot free, and that is the occupancy test everywhere. 1 move, 2 attack/aim, 4 kneel, 5 stand, 6 face/turn, 7 turn-then-attack, 8 timed wait, 9 mine-arm, 0xa teleport-jump, 0xb advance-with-defstat, 0x1c/0x1e markers, 0x1d/0x1f stance toggle, 0x40 run, 0x46 clear, 0x47 advance/repeat, 0x7f stop/interrupt. Full table: docs/fx-weapons.md 'Command queue op codes'.
    uint16_t arg0; // Per-op. op 1 (MOVE): destination tile COLUMN (read at 0x0042fe66, passed to llm_tact_move_step_attempt). op 6: direction 1..0x18. op 0x47: the run length written at 0x0042b55b and read back as the resubmit count at 0x004306d5.
    uint16_t arg1; // Per-op. op 1 (MOVE): destination tile ROW (read at 0x0042fe52).
    uint16_t arg2; // Per-op. For op 1 (MOVE) this is SCRATCH, not an input: rewritten from _G_LLM_TACT_MOVE_FLOOD_RESULT_COL on each pathfind (0x0042ff1c/0x0042ff31, 0x0043006e-0x0043008a). arg0 == arg2 && arg1 == arg3 is the ARRIVAL test (0x004300e7-0x00430118, which then calls llm_tact_unit_cmd_advance).
    uint16_t arg3; // Per-op. For op 1 (MOVE) the scratch counterpart of arg2, from _G_LLM_TACT_MOVE_FLOOD_RESULT_ROW (0x0042ff38/0x0042ff4d).
};

