    uint16_t building;
    uint8_t unit[2]; // llm_map_tile_unit_slot -- Two incompatible readings of the same 2 bytes, by game mode -- see llm_map_tile_unit_slot. `._` = strategic unit_id/player (the default); `.tact` = the tactical two-layer sprite overlay; `.f` = the raw word.
