// tact_unit_record (size 0x5f4, Ghidra category /Manual/game)
struct mh_tact_unit_record {
    uint8_t type; // building type id; 0=empty (guard <=0x80); indexes anim descriptor DAT_008742d8 + type*0x6c
    uint8_t owner; // side/faction (character WHO); projectile with equal fx_record.owner does no damage. Was 'hidden_flag'.
    uint8_t status; // bits: 1=owned/selection marker, 8=FIRE, 0x60=active/animated
    uint8_t pos_col; // anchor tile column (checked in destroy: tile_objects[pos_col][pos_row].building == id)
    uint8_t pos_row; // anchor tile row; building occupies a 2x2 tile footprint
    uint8_t anim_state; // 0/1 timed-move, 2/3/4 progress anims, 0x1f special
    uint8_t def_stat; // 'def' value shown in debug overlay
    uint16_t vision_angle; // = character.angle_see at spawn
    uint8_t vision_dist; // = character.distance_see at spawn
    uint8_t facing_dir; // facing 0..0x17 (0x18->1); selects directional sprite
    double move_state_timer; // Multi-purpose per-tick state clock used by llm_tact_unit_move_tick, and it means three different things. NORMAL path: accumulates the dt parameter every call (FLD 0x00430349 / FADD [EBP+0x8] 0x0043034f / FSTP 0x00430352; same shape at 0x0042fcbc-0x0042fcc5). KNEEL path (anim_state 2 or 3, tested 0x0042fbc6/0x0042fbd6): advanced by the character type's fixed kneel_time instead of dt (FLD [EDX*0x6c+0x873c38] 0x0042fc02, FADD 0x0042fc08, FSTP 0x0042fc0e) then jumps past the normal trailer at 0x0042fc14. DOOR path: OVERWRITTEN with the absolute time_GetCurrentTime() value, not an add (0x00430207-0x00430213). Elapsed time in two modes, a timestamp in the third -- do not assume one reading.
    double weapon_timer; // last-fire timestamp (llm_tact_unit_fire_weapon turret update)
    double wander_check_time; // Timestamp of this unit's last idle-wander evaluation. llm_tact_unit_owner_tick re-rolls a wander direction only once time_GetCurrentTime() exceeds wander_check_time + _G_LLM_TACT_UNIT_WANDER_RETRY_INTERVAL (FLD 0x00433b42 / FADD [0x005004ac] 0x00433b48 / FCOMP 0x00433b56 / JBE 0x00433b5c), then restamps it (0x00433b62-0x00433b6e) and enqueues a FACE/TURN command (op 6) at 0x00433bf9.
    double cmd_wait_until_time; // Absolute time_GetCurrentTime() deadline for a pending timed-WAIT command (queue op 8). Set to now + (double)cmd_queue[cmd_index].arg0 at 0x0042f708-0x0042f71d, and the dispatch loop keeps re-issuing the wait -- skipping the op switch entirely -- while now is below it (FLDZ/FCOMP-vs-0 guard at 0x0042f599, FCOMP-vs-now at 0x0042f5b2), all in llm_tact_unit_weapons_tick. Zeroed by two back-to-back 32-bit MOV-0 stores -- the compiler's zero-a-double idiom, NOT two fields -- when a MOVE (op 1) is dispatched (0x0042f767 + 0x0042f771) and at spawn (0x0042babd + 0x0042bac7). This subsumes what the decompiler rendered as field_0x23 and field_0x27; the FSTP at 0x0042f71d proves the 8-byte width.
    double anim_frame_time; // timestamp of last frame advance
    uint8_t frame_index; // current animation frame 0..0x1f
    double anim_cycle_time; // timestamp of animation cycle start
    double frame_interval; // seconds per animation frame
    uint8_t progress; // action/movement progress; drives 2/3/4 anim states and move offset
    uint16_t sprite_id; // current display sprite id (output; drawn by llm_tact_unit_render)
    int16_t move_path_slot; // Index of the global pathfinder path slot assigned to this unit's current move (mirrors _G_LLM_TACT_MOVE_PATH_SLOT_ID), 0 = none. While nonzero llm_tact_unit_move_tick skips re-pathing and goes straight to consuming the existing path (CMP 0x0042ff5b / JNZ 0x0042ff63 -> 0x00430091). Assigned from the global at 0x0042feed-0x0042fef4 and 0x00430031; cleared on arrival at 0x00430155 with the slot-flag release at 0x00430147. Sentinel -1 in the GLOBAL means no path found (tested 0x0042feb8).
    int16_t move_path_step; // Step index within the slot named by move_path_slot: the per-tick facing byte is fetched at _G_LLM_STRAT_PATH_BUFFERS + move_path_slot*0x258 + move_path_step*2 (MOVZX 0x0042fd3c / ADD EAX,EAX 0x0042fd43 / MOVZX [EAX+0xaee8c0] 0x0042fd47) and fed to llm_tact_facing_to_delta at 0x0042fd5a. Zeroed whenever a new slot is assigned (0x0042ff13, 0x00430050). The INCREMENT site is NOT in move_tick -- believed to be llm_tact_unit_move_advance (0x00430f5a), unverified.
    uint16_t hp; // hit points; llm_tact_fx_update_projectile subtracts fx_type.damage; <=damage -> anim_state 0x1f (dying)
    int16_t move_retry_wait; // Inner countdown in ticks before the next fast pathfinding retry. Decremented once per llm_tact_unit_move_tick call while above 0 (DEC 0x0042fcae, guarded 0x0042fca5). Reset to 0x10 at every site that also resets move_retry_attempts to 0xc: 0x0042fcec, 0x0042fed8, 0x00430005, 0x00430268. Also serves as the has-a-live-move-command gate in llm_tact_unit_owner_tick (CMP 0x00433670 / JZ 0x00433678).
    int16_t move_retry_attempts; // Retries remaining for a blocked move; decremented once each time move_retry_wait reaches 0, i.e. once per real retry (DEC 0x0042fcfc, guarded 0x0042fcd7/0x0042fcdf which falls through to move_stuck_countdown when already 0). Reset to 0xc at 0x0042fed8, 0x00430005 and 0x00430278, always paired with move_retry_wait = 0x10.
    int16_t move_stuck_countdown; // Outer give-up budget for a stuck move command, consumed once per exhausted fast-retry cycle (guard 0x0042fddf/0x0042fde7, DEC 0x0042fdf4, re-test 0x0042fe02/0x0042fe0a). On reaching 0 the command is ABORTED: the low byte of the current queue entry's op is snapshotted into move_aborted_op (MOV AL,[EAX+0x826125] 0x0042fe20 / MOV [EDX+0x8266ba],AL 0x0042fe26) and llm_tact_unit_cmd_advance is called (0x0042fe32). Reset to 3 at 0x00430015 and 0x00430288 alongside move_retry_wait/attempts.
    uint8_t cmd_index; // current command-queue index (was 'weapon_subindex')
    struct mh_llm_tact_unit_cmd_entry cmd_queue[128]; // Circular command queue: 0x80 entries x 0xb bytes, spanning +0x54..+0x5d3 with NO slack. Head is cmd_index (+0x53), advanced with wrap at 0x80 by llm_tact_unit_cmd_advance (0x0043133c-0x00431359); every wrap in the file tests `0x7f < idx`, so index 0x80 is unreachable and +0x5d4 is a separate field rather than entry 128. Written by llm_tact_unit_enqueue_command (0x0042b39d), consumed by llm_tact_unit_owner_tick / llm_tact_unit_move_tick, re-submitted by llm_tact_unit_cmd_queue_resubmit_run (0x0043069e).  BASE CORRECTED FROM +0x55 TO +0x54 on 2026-08-24 (finding 2026-08-24-1151-11). The old model documented 0xb-byte entries carrying only 10 bytes of named content and left an unexplained spare at the END of every entry; the leading byte was modelled separately as `cmd_slot_flag` with the other five fields as 'ENTRY-0 ALIAS' scalars. Both models predict the SAME addresses for every field that was already documented, so no earlier reading depended on +0x55. Five independent sites decide it, all indexing base 0x826124 (= unit 0 +0x54) with stride 0xb at ONE index: the enqueue's six-store block (0x0042b88f-0x0042b90a), the resubmit's six-read reconstruction (0x004306f5-0x0043076e), the two occupancy guards (0x00433641/0x00433658 and 0x0042b400/0x0042b416), and the debug overlay that prints flag and op for the same slot. The far-end objection dissolves too: +0x5d4..+0x5de and +0x5df..+0x5e9 are two MORE records of this identical 0xb-byte shape -- the immediate ATTACK/AIM and FACE/TURN slots the enqueue writes wholesale on its op==2 and op==6 short-circuits (0x0042b79f-0x0042b7f2, 0x0042b72c-0x0042b77a) -- and the third of them ends exactly where move_aborted_op begins at +0x5ea. Three records tile perfectly with zero orphan bytes. See docs/dead-ends.md L1: derive a record's base from the LOWEST offset any instruction touches with the stride, not from the first field you named.
    uint8_t attack_interrupt_flag; // interrupt_flag of the immediate ATTACK/AIM command record at +0x5d4 (the same 0xb-byte shape as mh_llm_tact_unit_cmd_entry; its op is attack_cmd_op at +0x5d5). Set from llm_tact_unit_enqueue_command's interrupt_flag parameter at 0x0042b79f on the op==2 short-circuit. LEAD, not settled: no reader was found -- the role is inferred from the position/shape parallel with the FACE record's face_interrupt_flag, which DOES have one.
    uint16_t attack_cmd_op; // op field of an IMMEDIATE (non-queued) command record at +0x5d4 that has the SAME 0xb-byte llm_tact_unit_cmd_entry shape: interrupt_flag +0x5d4, op +0x5d5, arg0 +0x5d7, arg1 +0x5d9, arg2 = aim_x +0x5db, arg3 = aim_y +0x5dd, ending +0x5de. Written wholesale by llm_tact_unit_enqueue_command's op==2 ATTACK/AIM short-circuit (0x0042b79f-0x0042b7f2) and reset to 0 by the op 0x46 CLEAR (0x0042b65b). A twin record for FACE/TURN occupies +0x5df..+0x5e9 (written 0x0042b72c-0x0042b77a, its op at +0x5e0), landing exactly on move_aborted_op at +0x5ea. These two immediate slots are why the queue's far end at +0x5d4 is not a hole. Deliberately NOT retyped as llm_tact_unit_cmd_entry: doing so would fold the hand-named, separately documented aim_x/aim_y into arg2/arg3 (finding 2026-08-24-1151-11, recommendation (a)). Renamed from field_5d5 2026-08-24.
    uint16_t attack_gun_toggle; // arg0 of the immediate ATTACK/AIM record. Passed as fire_arg to llm_tact_unit_fire_weapon (load 0x0042f401, call 0x0042f40e), which XORs it with active_gun at 0x00430925 to pick the firing gun -- so 0 fires the currently active gun and 1 fires the other. Written from the enqueue's arg0 at 0x0042b7bf; zeroed at spawn (0x0042bd5f).
    uint16_t attack_cmd_arg1; // arg1 slot of the immediate ATTACK/AIM record, written wholesale with the rest of it (0x0042b7d0) and zeroed at spawn (0x0042bd6f). NO READER FOUND anywhere in the exported tactical set: it exists because the record shares the 0xb-byte cmd_entry shape and the enqueue fills every arg slot. Scaffolding name -- a LEAD, not a reading.
    uint16_t aim_x; // current target/aim X (weapon logic)
    uint16_t aim_y; // current target/aim Y
    uint8_t face_interrupt_flag; // interrupt_flag of the immediate FACE/TURN command record at +0x5df (0xb-byte cmd_entry shape; its op is face_cmd_op at +0x5e0). Set from the enqueue's interrupt_flag parameter at 0x0042b72c, and READ as part of the re-entry guard that refuses to re-issue a FACE onto an already-armed slot (CMP at 0x0042b6f3, paired with the face_cmd_op==6 test at 0x0042b6e0).
    uint16_t face_cmd_op; // op of the immediate FACE/TURN record: 6 = turn pending, 0 = free/consumed. Armed to 6 by llm_tact_unit_enqueue_command's op==6 short-circuit (0x0042b739) and by the op-7 turn-then-attack path in llm_tact_unit_weapons_tick (0x0042f477). Cleared to 0 by llm_tact_unit_rotate_tick once facing_dir reaches face_cmd_target_dir, or immediately if status bit 0x8 (FIRE) is set (0x004307f9, 0x00430843), and by the op 0x46 CLEAR in both enqueue_command (0x0042b64b) and llm_tact_group_issue_order (0x0042b258). Read as the 'is it turning' gate before calling rotate_tick (0x0042f4e4 -> call 0x0042f504).
    uint16_t face_cmd_target_dir; // arg0 of the immediate FACE/TURN record: the target dir24 heading (1..0x18) to rotate to. Written from the enqueue's arg0 (0x0042b74c) or from cmd_queue[idx].arg0 on the op-7 path (0x0042f49b). llm_tact_unit_rotate_tick compares it against facing_dir (load 0x00430819, CMP 0x00430820) and passes it to llm_tact_unit_rotate_step (0x0043082b/0x00430835) until they match.
    uint16_t face_cmd_arg1; // arg1 slot of the immediate FACE/TURN record. Written 0 by every writer found (0x0042b75a, 0x0042f4a9); no reader anywhere in the exported tactical set. Unused payload of the shared 0xb-byte cmd_entry shape -- scaffolding name, a LEAD.
    uint16_t face_cmd_arg2; // arg2 slot of the immediate FACE/TURN record. Written 0 at 0x0042b76a and 0x0042f4b9; no reader found. See face_cmd_arg1.
    uint16_t face_cmd_arg3; // arg3 slot of the immediate FACE/TURN record. Written 0 at 0x0042b77a and 0x0042f4c9; no reader found. It completes the record at +0x5df..+0x5e9 with zero orphan bytes, landing exactly on move_aborted_op at +0x5ea. See face_cmd_arg1.
    uint8_t move_aborted_op; // Low byte of cmd_queue[cmd_index].op snapshotted at the moment move_stuck_countdown expires and the command is force-dequeued (MOV AL,[EAX+0x826125] 0x0042fe20 / MOV [EDX+0x8266ba],AL 0x0042fe26) -- which op was interrupted by a stuck move. Sole write site; no reader found in llm_tact_unit_move_tick, llm_tact_unit_owner_tick or llm_tact_render_view.
    uint8_t active_gun; // Selected weapon slot, 0 = gun1, 1 = gun2. Used as a +0/+1 bias onto llm_tact_character_type.height_gun1 (+0x1e) when computing the firing-line height: MOVZX type 0x004337ed / IMUL 0x6c 0x004337ea / MOVZX this 0x004337f4 / ADD 0x004337fb / MOVZX [EAX+0x873c22] 0x004337fd, where 0x873c22 = _G_LLM_TACT_CHARACTER_TYPES (0x00873c04, llm_tact_character_type[16]) + 0x1e; repeated at 0x004338dd and 0x00433a44. Printed raw as the gun:%1d field of llm_tact_render_view's debug overlay (0x0042d94d, sprintf 0x0042d96e). NOTE the decompiled C renders this as character_type.name[field_0x5eb + 0x1e] because name is at +0 and Ghidra folds the +0x1e into the index -- it is NOT a name-table lookup. No write site found in the three readers.
    uint8_t gun1_bullets; // = fx_type[gun1].bullets at spawn; decremented per shot
    uint8_t gun2_bullets; // = fx_type[gun2].bullets at spawn
    uint8_t gun1_magazines; // = fx_type[gun1].magazines - 1 at spawn
    uint8_t gun2_magazines; // = fx_type[gun2].magazines - 1 at spawn
    uint8_t squad_group_id; // Player-assigned squad / control-group id, 0..7, with 0xff = unassigned (the spawn default, set at 0x0042bdad). llm_tact_ui_sel_panel_multi_mode_tick writes the active group (_G_LLM_TACT_SIDEBAR_ACTIVE_GROUP_ID) into every selected owner-0 unit at 0x00436336 ('assign to group') and re-selects every unit whose value matches it at 0x00436390/0x00436397 ('recall group'). llm_tact_sidebar_dispatch sets it from a sidebar icon click (0x00435adc) or resets it to 0xff (0x00435b01). llm_tact_squad_roster_refresh buckets every active unit by it (0x0043575f/0x00435769) into _G_LLM_TACT_UNASSIGNED_UNIT_ROSTER or _G_LLM_TACT_GROUP_UNIT_ROSTER[id]. ENUM candidate (8 groups + the 0xff sentinel).
    uint8_t move_redirect_col; // Scratch tile COLUMN for re-targeting an in-flight MOVE. Snapshotted from pos_col whenever the command queue is CLEARed (op 0x46) -- 0x0042b5ce in enqueue_command, 0x0042b1f1 in llm_tact_group_issue_order. group_issue_order then uses it (with move_redirect_row) as the current-position input to llm_tact_move_step_attempt (0x0042b2c7/0x0042b2ce) and llm_tact_move_path_preview_walk (0x0042b2fe/0x0042b309), overwriting it with the walked-forward column at 0x0042b318. llm_tact_frame also reads it at 0x0042a873 to compute the click-preview facing. Confidence MEDIUM on the name -- the mechanism is traced, the intended concept is not.
    uint8_t move_redirect_row; // Row counterpart of move_redirect_col, snapshotted from pos_row. Written 0x0042b5e8, 0x0042b20b, 0x0042b328; read 0x0042b2b9, 0x0042b2f0, 0x0042a884.
    uint8_t click_preview_facing; // dir24 heading (0..0x17) computed per frame by llm_tact_frame's click-preview overlay for selected units with status bits 0x41, from llm_tact_calc_dir24(camera+cursor vs move_redirect_col/row) -- call 0x0042a8ba, store 0x0042a8e6. Consumed by llm_tact_group_issue_order at 0x0042b108 as an OVERRIDE for the order's target-direction argument when the order code is 7 (turn-then-attack), i.e. the live UI preview direction becomes the actual attack facing at issue time.
};

